export default jobs;

export function getJobsByCity(city) {
  return jobs.filter(j => j.city?.toLowerCase() === city?.toLowerCase());
}

export function getJobsByState(state) {
  return jobs.filter(j => j.state?.toLowerCase() === state?.toLowerCase());
}

export function getJobsByTitle(titlePattern) {
  return jobs.filter(j => j.title?.toLowerCase().includes(titlePattern?.toLowerCase()));
}
